head.script:
// 테스트 설명, 유효성 값 설정
//  ※ 본 샘플(_6)은 groupbyHeader/groupbyFooter 를 "객체 형식"(depth_{n} 키)으로 설정할 때
//    Group Depth 별로 서로 다른 형식이 각 Depth Header/Footer Row 에 매핑되는지 검증한다.
//    (하위 속성 개별 동작(colSpan/inputType/align 등)의 전수검증은 _2, rowNum/rowStatus Header/Footer 는 _9 담당이므로
//     여기서는 객체형 Header/Footer 의 Depth 별 매핑에 집중)
scwin.tData = {
    "description" : "[gridView > M > groupby]<br/>Body Column 을 기준으로 데이터를 그룹핑하여 Group Header/Footer 함께 표시합니다.",
    "validation" : [
        "groupbyHeader(선택) 파라미터를 객체 형식으로 설정 시, Group Depth 별로 다른 형식을 적용할 수 있습니다.",
        "groupbyHeader(선택) 객체 형식은 'depth_{depth}' 형식의 키값을 사용하며 각 키에는 객체 배열을 값으로 설정해야 합니다. (depth_0 은 Depth 0 Group Header Row 에, depth_1 은 Depth 1 Group Header Row 에 매핑됩니다)",
        "groupbyFooter(선택) 파라미터를 객체 형식으로 설정 시, Group Depth 별로 다른 형식을 적용할 수 있습니다. (하위 파라미터 구조는 groupbyHeader 와 동일)",
        "groupbyFooter(선택) 객체 형식은 'depth_{depth}' 형식의 키값을 사용하며 각 키에는 객체 배열을 값으로 설정합니다. (depth_0 은 Depth 0 Group Footer Row 에, depth_1 은 Depth 1 Group Footer Row 에 매핑됩니다)"
    ]
}



scwin.onpageload = async function () {
    // 공통 DataList(gdl_boolean 등) 생성
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 4컬럼(지역/부서/등급/점수) 그리드를 지역(idx0) > 부서(idx1) 2Depth 로 groupby.\n[절차] 초기 로드 시 그룹핑 안 된 평평한 그리드 → (groupby 실행) 클릭 시 groupbyHeader/groupbyFooter 를 객체 형식 (depth_0 / depth_1) 으로, depth 마다 다른 집계식(실사용 SubTotal)으로 설정하여 groupby 적용.\n[확인] depth_0 Header=지역명(토글)+점수 max, depth_1 Header=부서명(토글)+점수 sum 처럼 Depth 별 다른 집계식이 적용되고, Footer 도 depth_0=지역 건수(count) / depth_1=부서 평균(avg) 로 매핑됨.\n[확인] Header/Footer × depth_0/1 4종 그룹행에 서로 다른 배경색을 지정 → 결과창에서 4종 배경색이 다르게 적용됨을 실측."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) : _1~_3 통일 스키마 (지역/부서/등급/점수) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="region" name="지역" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="부서" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="등급" dataType="text"></w2:column>';
    strDlt += '<w2:column id="score" name="점수" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 지역(region) > 부서(dept) 2Depth 그룹 반복 데이터 (_1~_3 통일 데이터)
    let jsonData = [
        { "region": "부산", "dept": "기획", "grade": "C", "score": 60 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 20 },
        { "region": "서울", "dept": "영업", "grade": "B", "score": 40 },
        { "region": "부산", "dept": "영업", "grade": "B", "score": 50 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 10 },
        { "region": "서울", "dept": "개발", "grade": "A", "score": 30 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성 (Body 4컬럼, body column id = DataList 컬럼 id 일치)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' defaultCellHeight="28" dataList="data:dlt_bind" id="" style="width:620px;height:640px;">';
    strTarget += '<w2:caption style="" id="caption1" value="groupby depth 객체형식 Header/Footer 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol1" value="지역(0)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol2" value="부서(1)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol3" value="등급(2)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol4" value="점수(3)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="region" dataList="region"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="grade" dataList="grade"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" dataType="number" displayFormat="#,###" id="score" dataList="score"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
};



// [groupby 실행] : groupbyHeader/groupbyFooter 를 객체(depth_{n}) 형식으로, Depth 마다 다른 집계식(실사용 SubTotal)으로 설정 후 depth 별 배경색 실측
//  - 하위 속성(colSpan/inputType/align 등) 전수검증은 _2, rowNum/rowStatus Header/Footer 는 _9 담당 → 여기서는 객체형 Header/Footer 의 Depth 구분에 집중
//  - depth_0 Header=지역명(토글)+max / depth_1 Header=부서명(토글)+sum, depth_0 Footer=지역 건수+count / depth_1 Footer=부서 평균+avg (depth 별 다른 집계식)
//    · 검증은 엔진이 그룹행에 자동 부착하는 w2grid_groupby_depth_0/1 클래스의 배경색을 getComputedStyle 로 실측해 depth_0 ≠ depth_1 을 확인
scwin.btn_groupby_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");

    let options = {
        sortIndex: [0, 1],   // 지역(region) > 부서(dept) → 2 Depth (groupby 전제, _1 담당)
        sortOrder: [1, 1],
        // groupbyHeader 객체 형식 : depth_0(지역) 과 depth_1(부서) 에 서로 다른 형식 적용 — 실사용 SubTotal 형태
        //  · 첫 Column : toggle()+depthStr() → 그룹 토글 + 그룹명(지역명/부서명)
        //  · 점수 Column : depth_0=max(지역 최고점수) / depth_1=sum(부서 합계)  ← depth 별 다른 집계식(샘플 본질)
        groupbyHeader: {
            depth_0: [
                { inputType: "expression", expression: "toggle() + depthStr()", align: "left" },
                {},
                {},
                { inputType: "expression", expression: "max('score')", align: "right" }
            ],
            depth_1: [
                { inputType: "expression", expression: "toggle() + depthStr()", align: "left" },
                {},
                {},
                { inputType: "expression", expression: "sum('score')", align: "right" }
            ]
        },
        // groupbyFooter 객체 형식 : depth_0(지역) 과 depth_1(부서) 에 서로 다른 형식 적용 — 실사용 SubTotal 형태
        //  · 첫 Column : 자연스러운 집계 라벨 · 집계 Column : depth_0=count(지역 건수) / depth_1=avg(부서 평균)  ← depth 별 다른 집계식
        groupbyFooter: {
            depth_0: [
                { value: "지역 건수", align: "left" },
                {},
                {},
                { inputType: "expression", expression: "count()", align: "right" }
            ],
            depth_1: [
                { value: "부서 평균", align: "left" },
                {},
                {},
                { inputType: "expression", expression: "avg('score')", align: "right" }
            ]
        }
    };

    if (target1.groupbyStatus && target1.groupbyStatus.grouped) {
        target1.clearGroupby();
    }
    target1.groupby(options);

    // === 검증 : Group Header/Footer 각각 depth_0/depth_1 그룹행 배경색을 실측해 depth 별로 다름을 확인 ===
    //  · 엔진은 그룹행 td 에 depth 클래스(w2grid_groupby_depth_0/1)만 부착하고 Header/Footer 구분 클래스는 별도로 두지 않는다(DOM 실측 확인).
    //    Header 그룹행 첫 셀에는 toggle() 아이콘(span.w2grid_minus/plus)이 있고 Footer 그룹행에는 없으므로, 측정 시 이 아이콘 유무로 Header/Footer 를 구분한다.
    //  · 배경색은 depth 클래스로 결정 → Header depth_0 ≠ Header depth_1, Footer depth_0 ≠ Footer depth_1 이 성립함을 getComputedStyle 로 확인.
    let tbody = document.getElementById(target1.id + "_body_tbody");
    let groupCellBg = function (depth, wantFooter) {
        let tds = tbody.querySelectorAll("td.w2grid_groupby_depth_" + depth);
        for (let i = 0; i < tds.length; i++) {
            let row = tds[i].parentNode;
            let isFooter = !row.querySelector(".w2grid_minus, .w2grid_plus"); // 토글 아이콘 없으면 Footer 그룹행
            if (isFooter === wantFooter) return window.getComputedStyle(tds[i]).backgroundColor;
        }
        return "(없음)";
    };
    let hb0 = groupCellBg(0, false);  // Header depth_0
    let hb1 = groupCellBg(1, false);  // Header depth_1
    let fb0 = groupCellBg(0, true);   // Footer depth_0
    let fb1 = groupCellBg(1, true);   // Footer depth_1

    // 출력 : Header 2종 + Footer 2종 = 4종 배경색 실측 (간결)
    let out = "[검증] 엔진 기본 클래스(depth) + Header/Footer(toggle 아이콘 유무)로 4종 그룹행에 서로 다른 배경색 지정."
        + "\n[Header] depth_0 배경=" + hb0 + " / depth_1 배경=" + hb1
        + "\n[Footer] depth_0 배경=" + fb0 + " / depth_1 배경=" + fb1;
    b.setReturnValue(out);
};
